(()=>{'use strict';if(new URL(location.href).searchParams.get('descriptionQrRescan')!=='confirmed')return;let button;
const targets={'#MON-01':'49261c1e-02c7-49f9-aa9a-9237781cae57','#JNL-03':'c6e5910f-4375-4966-989f-7e4a7f630344'};
const lines=['- 동일 행사에서 동일 사용자가 상담 중인 동일 기업의 QR을 재스캔하면 “현재 진행 중인 상담입니다.”를 안내한다.','- 새 상담을 생성하지 않고 기존 상담일지 등록 화면(JNL-04/JNL-05)으로 연결한다.','- 기존 상담일지에 입력·저장된 내용을 유지한다.','- 기존 진행 상담을 유지하며 진행 상담 건수에 추가 집계하지 않는다.'];
function setup(){const store=window.GFAIR_COLLAB;if(!targets[location.hash]||!store?.user?.editor||button)return;button=document.createElement('button');button.className='btn';button.textContent='동일 QR 재스캔 확정 정책 저장';button.style.cssText='position:fixed;right:24px;bottom:20px;z-index:100000;background:#fff;padding:12px;border:2px solid #333';document.body.append(button);
button.onclick=async()=>{button.disabled=true;try{await store.refresh(true);const record=store.records.find(r=>r.id===targets[location.hash]);if(!record)throw Error('해당 설명을 찾지 못했습니다.');const spec=JSON.parse(record.text);const added=lines.join('\n');if(!spec.policy.includes(lines[0]))spec.policy=(spec.policy||'').trim()+'\n'+added;
spec.planningNote=(spec.planningNote||'').split('\n').filter(line=>!line.includes('상담 중 동일 QR 재스캔 시 기존 상담 유지·중복 생성 방지 방식 협의 필요')).join('\n').trim();
const start=spec.policy.indexOf(added);spec.codexHighlights={...(spec.codexHighlights||{}),policy:[...(spec.codexHighlights?.policy||[]).filter(range=>range.end<=start),{start,end:start+added.length,text:added}]};delete spec.codexHighlights.planningNote;
await store.mutate('update',{id:record.id,revision:record.revision,text:JSON.stringify(spec)});button.textContent='확정 정책 서버 저장 완료';window.dispatchEvent(new Event('annotation-render'));}catch(error){button.textContent=error.message;button.disabled=false;}};}
window.addEventListener('collaboration-updated',setup);setup();})();